130	pub(crate) struct PackedLoraProjection {
131	    pub(crate) a: cudarc::driver::CudaSlice<bf16>,
132	    pub(crate) b: cudarc::driver::CudaSlice<bf16>,
133	    pub(crate) scales: cudarc::driver::CudaSlice<f32>,
134	    pub(crate) max_loras: usize,
135	    pub(crate) max_rank: usize,
136	    pub(crate) rank: usize,
137	    in_dim: usize,
138	    pub(crate) out_dim: usize,
139	    slot_ranks: Vec<usize>,
140	}
141	
142	impl PackedLoraProjection {
143	    fn new(
144	        ctx: &DeviceContext,
145	        max_loras: usize,
146	        max_rank: usize,
147	        in_dim: usize,
148	        out_dim: usize,
149	    ) -> Result<Self> {
150	        let a_elems = max_loras * max_rank * in_dim;
151	        let b_elems = max_loras * out_dim * max_rank;
152	        let a = ctx
153	            .stream
154	            .alloc_zeros(a_elems)
155	            .map_err(|e| anyhow::anyhow!("packed LoRA A alloc failed: {e}"))?;
156	        let b = ctx
157	            .stream
158	            .alloc_zeros(b_elems)
159	            .map_err(|e| anyhow::anyhow!("packed LoRA B alloc failed: {e}"))?;
160	        let scales = ctx
161	            .stream
162	            .alloc_zeros(max_loras)
163	            .map_err(|e| anyhow::anyhow!("packed LoRA scales alloc failed: {e}"))?;
164	        Ok(Self {
165	            a,
166	            b,
167	            scales,
168	            max_loras,
169	            max_rank,
170	            rank: 0,
171	            in_dim,
172	            out_dim,
173	            slot_ranks: vec![0; max_loras],
174	        })
175	    }
176	
177	    fn write_slot(
178	        &mut self,
179	        ctx: &DeviceContext,
180	        slot: usize,
181	        projection: &DeviceLoraProjection,
182	        scale: f32,
183	    ) -> Result<()> {
184	        anyhow::ensure!(slot < self.max_loras, "packed LoRA slot out of range");
185	        anyhow::ensure!(
186	            projection.a.rows <= self.max_rank && projection.a.cols == self.in_dim,
187	            "inconsistent LoRA A shape in packed projection"
188	        );
189	        anyhow::ensure!(
190	            projection.b.rows == self.out_dim && projection.b.cols == projection.a.rows,
191	            "inconsistent LoRA B shape in packed projection"
192	        );
193	        self.clear_slot(ctx, slot)?;
194	
195	        let rank = projection.a.rows;
196	        let a_src = projection.a.data.slice(..rank * self.in_dim);
197	        let a_offset = slot * self.max_rank * self.in_dim;
198	        let mut a_dst = self.a.slice_mut(a_offset..a_offset + rank * self.in_dim);
199	        ctx.stream
200	            .memcpy_dtod(&a_src, &mut a_dst)
201	            .map_err(|e| anyhow::anyhow!("packed LoRA A copy failed: {e}"))?;
202	
203	        let b_offset = slot * self.out_dim * self.max_rank;
204	        pegainfer_core::ops::pack_lora_b_rows_into(
205	            ctx,
206	            &projection.b.data,
207	            &mut self.b,
208	            b_offset,
209	            rank,
210	            self.max_rank,
211	            self.out_dim,
212	        )
213	        .map_err(|e| anyhow::anyhow!("packed LoRA B copy failed: {e}"))?;
214	
215	        let mut scale_slot = self.scales.slice_mut(slot..=slot);
216	        ctx.stream
217	            .memcpy_htod(&[scale], &mut scale_slot)
218	            .map_err(|e| anyhow::anyhow!("packed LoRA scale copy failed: {e}"))?;
219	        self.slot_ranks[slot] = rank;
220	        self.refresh_rank();
221	        Ok(())
222	    }
223	
224	    fn clear_slot(&mut self, ctx: &DeviceContext, slot: usize) -> Result<()> {
225	        anyhow::ensure!(slot < self.max_loras, "packed LoRA slot out of range");
226	
227	        let zero_a = vec![bf16::ZERO; self.max_rank * self.in_dim];
228	        let a_offset = slot * self.max_rank * self.in_dim;
229	        let mut a_dst = self
230	            .a
231	            .slice_mut(a_offset..a_offset + self.max_rank * self.in_dim);
232	        ctx.stream
233	            .memcpy_htod(&zero_a, &mut a_dst)
234	            .map_err(|e| anyhow::anyhow!("packed LoRA A clear failed: {e}"))?;
235	
236	        let zero_b = vec![bf16::ZERO; self.out_dim * self.max_rank];
237	        let b_offset = slot * self.out_dim * self.max_rank;
238	        let mut b_dst = self
239	            .b
240	            .slice_mut(b_offset..b_offset + self.out_dim * self.max_rank);
241	        ctx.stream
242	            .memcpy_htod(&zero_b, &mut b_dst)
243	            .map_err(|e| anyhow::anyhow!("packed LoRA B clear failed: {e}"))?;
244	
245	        let mut scale_slot = self.scales.slice_mut(slot..=slot);
246	        ctx.stream
247	            .memcpy_htod(&[0.0f32], &mut scale_slot)
248	            .map_err(|e| anyhow::anyhow!("packed LoRA scale clear failed: {e}"))?;
249	        self.slot_ranks[slot] = 0;
250	        self.refresh_rank();
251	        Ok(())
252	    }
253	
254	    fn refresh_rank(&mut self) {
255	        self.rank = self.slot_ranks.iter().copied().max().unwrap_or(0);
256	    }
257	}
