447	    pub(crate) fn install_lora_adapter(
448	        &mut self,
449	        adapter: DeviceLoraAdapter,
450	        load_inplace: bool,
451	    ) -> Result<()> {
452	        debug!(
453	            "Installing Qwen3 LoRA adapter {} from {}",
454	            adapter.name,
455	            adapter.manifest.path.display()
456	        );
457	        let name = adapter.name.clone();
458	        let slot = self.packed_lora.slot_for_install(&name, load_inplace)?;
459	        if let Err(err) = self.update_packed_lora_slot(slot, &adapter) {
460	            self.lora_adapters.remove(&name);
461	            if self.packed_lora.slot_for(&name) == Some(slot) {
462	                let _ = self.packed_lora.release_slot(&name);
463	            }
464	            return Err(err).with_context(|| {
465	                format!(
466	                    "failed to update packed LoRA slot {slot} for adapter {name}; adapter was removed to keep packed decode state consistent"
467	                )
468	            });
469	        }
470	        install_lora_adapter_in_registry(&mut self.lora_adapters, adapter, load_inplace)?;
471	        self.packed_lora.bind_slot(slot, &name);
472	        Ok(())
473	    }
474	
475	    pub(crate) fn uninstall_lora_adapter(&mut self, name: &str) -> Result<()> {
476	        let slot = self
477	            .packed_lora
478	            .slot_for(name)
479	            .ok_or_else(|| anyhow::anyhow!("Qwen3 LoRA adapter {name} is not loaded"))?;
480	        self.clear_packed_lora_slot(slot)?;
481	        self.packed_lora.release_slot(name)?;
482	        self.lora_adapters
483	            .remove(name)
484	            .expect("packed LoRA slot map and adapter registry must be consistent");
485	        Ok(())
486	    }
487	
488	    pub(crate) fn discard_lora_adapter(&mut self, name: &str) -> Result<()> {
489	        if self.packed_lora.slot_for(name).is_some() {
490	            self.packed_lora.release_slot(name)?;
491	        }
492	        self.lora_adapters.remove(name);
493	        Ok(())
494	    }
495	
496	    fn lora_layer_for(&self, name: &str, layer_idx: usize) -> Option<(&DeviceLoraLayer, f32)> {
497	        self.lora_adapters.get(name).and_then(|adapter| {
498	            adapter
499	                .layers
500	                .get(layer_idx)
501	                .map(|layer| (layer, adapter.scale))
502	        })
503	    }
504	
505	    pub(crate) fn apply_lora_projection_ranges(
506	        &self,
507	        layer_idx: usize,
508	        groups: &[DeviceLoraTokenGroup<'_>],
509	        projection: impl for<'a> Fn(&'a DeviceLoraLayer) -> Option<&'a DeviceLoraProjection>,
510	        input: &HiddenStates,
511	        out: &mut HiddenStates,
512	        row_offset: usize,
513	    ) -> Result<()> {
514	        for group in groups {
515	            let Some((layer, scale)) = self.lora_layer_for(group.adapter, layer_idx) else {
516	                anyhow::bail!("Qwen3 LoRA adapter {} is not loaded", group.adapter);
517	            };
518	            if let Some(projection) = projection(layer) {
519	                if group.ranges.len() == 1 {
520	                    let range = group.ranges[0];
521	                    apply_lora_projection_delta_range(
522	                        &self.ctx,
523	                        projection,
524	                        input,
525	                        out,
526	                        row_offset,
527	                        range.token_offset,
528	                        range.token_len,
529	                        scale,
530	                    )?;
531	                } else {
532	                    let token_indices_d = group
533	                        .token_indices_d
534	                        .as_ref()
535	                        .expect("non-contiguous LoRA token group must have device indices");
536	                    apply_lora_projection_delta_indexed(
537	                        &self.ctx,
538	                        projection,
539	                        input,
540	                        out,
541	                        row_offset,
542	                        token_indices_d,
543	                        group.token_count,
544	                        scale,
545	                    )?;
546	                }
547	            }
548	        }
549	        Ok(())
550	    }
