580	    fn update_packed_lora_slot(&mut self, slot: usize, adapter: &DeviceLoraAdapter) -> Result<()> {
581	        self.clear_packed_lora_slot(slot)?;
582	        for layer_idx in 0..self.config.num_hidden_layers {
583	            let Some(layer) = adapter.layers.get(layer_idx) else {
584	                continue;
585	            };
586	            for kind in LoraProjectionKind::ALL {
587	                let Some(projection) = layer.projection(kind) else {
588	                    continue;
589	                };
590	                self.pack_lora_projection_slot(slot, projection, adapter.scale, layer_idx, kind)?;
591	            }
592	        }
593	        Ok(())
594	    }
