820	    /// Bytes one KV page costs in the pool, for a given page size. The single
821	    /// owner of this formula — callers that bill KV pages (hedge scratch,
822	    /// budgets) must not re-derive it.
823	    pub(crate) fn kv_page_bytes(&self, page_size: usize) -> Result<usize> {
824	        Self::kv_bytes_per_block(&self.kv_budget_geometry(page_size))
825	    }
826	
827	    fn kv_budget_geometry(&self, page_size: usize) -> KvBudget {
828	        let num_kv_heads = self.local_num_key_value_heads();
829	        KvBudget {
830	            num_layers: self.config.num_hidden_layers,
831	            num_kv_heads,
832	            head_dim: self.config.head_dim,
833	            block_size: page_size,
834	            num_blocks: 0,
835	        }
836	    }
837	
838	    fn kv_bytes_per_block(geometry: &KvBudget) -> Result<usize> {
839	        // Checked BEFORE constructing the layout: `KvLayout::new` derives its
840	        // strides with plain products, and this full product dominates every
841	        // partial one, so clearing it clears them all.
842	        let bytes = crate::sizing::product(&[
843	            geometry.num_layers,
844	            2,
845	            geometry.num_kv_heads,
846	            geometry.head_dim,
847	            geometry.block_size,
848	            std::mem::size_of::<half::bf16>(),
849	        ])?;
850	        let layout = pegainfer_kv_cache::KvLayout::new(
851	            geometry.num_layers,
852	            geometry.num_kv_heads,
853	            geometry.head_dim,
854	            geometry.block_size,
855	        );
856	        debug_assert_eq!(
857	            bytes,
858	            layout.page_stride * std::mem::size_of::<half::bf16>()
859	        );
860	        Ok(bytes)
861	    }
862	
863	    /// Smallest pool the scheduler can make progress with.
864	    const MIN_KV_BLOCKS: usize = 64;
865	
866	    fn kv_budget_from_bytes(
867	        mut geometry: KvBudget,
868	        bytes_per_block: usize,
869	        dflash_kv_bytes_per_token: usize,
870	        kv_budget_bytes: usize,
871	        free_bytes: usize,
872	        source: &'static str,
873	    ) -> Result<KvBudget> {
874	        // DFlash keeps its own per-request KV (plus prompt-scaling scratch) outside
875	        // the paged pool, scaling with the same token count. Charge it as extra
876	        // bytes per pool token so the target block count shrinks to leave room; the
877	        // pool itself is still allocated at the target-only `bytes_per_block`.
878	        //
879	        // Checked: the draft config is not shape-validated against the draft
880	        // weights until the model loads, which is after this budget is fixed.
881	        let effective_bytes_per_block = crate::sizing::sum(&[
882	            bytes_per_block,
883	            crate::sizing::product(&[dflash_kv_bytes_per_token, geometry.block_size])?,
884	        ])?;
885	        anyhow::ensure!(
886	            effective_bytes_per_block > 0,
887	            "KV budget ({source}): degenerate geometry gives zero bytes per block"
888	        );
889	        // Against `effective`, not `bytes_per_block`: a budget that affords 64
890	        // target blocks can still be short once the draft's out-of-pool KV is
891	        // charged, and forcing the floor anyway defers the shortfall into a
892	        // draft-growth OOM at serving time.
893	        let affordable = kv_budget_bytes / effective_bytes_per_block;
894	        anyhow::ensure!(
895	            affordable >= Self::MIN_KV_BLOCKS,
896	            "KV cache ({source}) affords only {affordable} blocks, below the \
897	             {}-block minimum: budget={} MiB, needed={} MiB \
898	             ({} KiB per block = {} target + {} draft)",
899	            Self::MIN_KV_BLOCKS,
900	            kv_budget_bytes / (1024 * 1024),
901	            crate::sizing::product(&[Self::MIN_KV_BLOCKS, effective_bytes_per_block])?
902	                / (1024 * 1024),
903	            effective_bytes_per_block / 1024,
904	            bytes_per_block / 1024,
905	            (effective_bytes_per_block - bytes_per_block) / 1024,
906	        );
907	        let num_blocks = affordable;
908	        // Saturating, not checked: log-only figures must not abort startup.
909	        // Reported on the same basis the blocks were derived from — pool and
910	        // draft split out, since only the pool shows up in the KV allocation.
911	        let pool_mb = num_blocks.saturating_mul(bytes_per_block) / (1024 * 1024);
912	        let draft_mb =
913	            num_blocks.saturating_mul(effective_bytes_per_block - bytes_per_block) / (1024 * 1024);
914	        let spent = num_blocks.saturating_mul(effective_bytes_per_block);
915	        let page_size = geometry.block_size;
916	        log::info!(
917	            "KV cache ({source}): {num_blocks} blocks (pool {pool_mb} MB + draft {draft_mb} MB, \
918	             page size {page_size}, {:.0}% of {:.0} MB free)",
919	            spent as f64 / free_bytes as f64 * 100.0,
920	            free_bytes as f64 / 1024.0 / 1024.0
921	        );
922	        geometry.num_blocks = num_blocks;
923	        Ok(geometry)
924	    }
925	}
