927	fn mem_info_bytes() -> Result<(usize, usize)> {
928	    let (free, total) = cudarc::driver::result::mem_get_info()
929	        .map_err(|e| anyhow::anyhow!("cuMemGetInfo failed: {e:?}"))?;
930	    Ok((free, total))
931	}
932	
933	fn profile_temp_blocks(
934	    max_prefill_tokens: usize,
935	    profile_decode_rows: usize,
936	    block_size: usize,
937	) -> usize {
938	    // Block 0 is reserved as the decode padding block. Worst-case scheduling can
939	    // run one max-sized prefill row plus the remaining decode rows.
940	    1 + max_prefill_tokens.div_ceil(block_size) + profile_decode_rows
941	}
