1	//! Scheduling mechanics: admission, KV-prefetch parking, chunked-prefill
2	//! batching, and plan selection for the dedicated GPU thread.
3	//!
4	//! This module is engine-contract-free: it owns queues of [`PendingRequest`]s
5	//! and produces pure [`effects::StepEffects`] data. The serve loop itself
6	//! belongs to the contract's driver, and everything that touches the engine
7	//! contract (typestate handles, emitter calls, the `Scheduler` trait) lives in
8	//! [`crate::frontend_adapter`] — read that file to see how Qwen3 plugs into
9	//! the frontend.
10	
11	pub(crate) mod effects;
12	pub(crate) mod phase_trace;
13	pub(crate) mod plan;
14	pub(crate) mod resolve;
15	
16	use std::collections::HashSet;
17	
18	use log::debug;
19	use log::warn;
20	use pegainfer_frontend::engine::Request;
21	use pegainfer_frontend::engine::StopPolicy;
22	use pegainfer_frontend::sampler::SamplingParams;
23	
24	use crate::executor::ModelExecutor;
25	use crate::executor::RequestId;
26	
27	// ── Internal types ──────────────────────────────────────────────────────
28	
29	/// An in-flight request being decoded.
30	pub(crate) struct ActiveRequestState {
31	    pub(crate) request_id: RequestId,
32	    pub(crate) lora_adapter: Option<String>,
33	    pub(crate) last_token: u32,
34	    pub(crate) generated_count: usize,
35	    pub(crate) max_tokens: usize,
36	    pub(crate) prompt_len: usize,
37	    pub(crate) params: SamplingParams,
38	    pub(crate) stop_policy: StopPolicy,
39	    /// Completion top-k count; None disables scoring, Some(0) scores only the chosen token.
40	    pub(crate) logprobs: Option<usize>,
41	}
42	
43	/// A request between submission and promotion, `Clone` because the decode-overlap
44	/// path keeps a copy for async-prefill poll resolution. Its engine-contract
45	/// handle lives in the adapter's registry, keyed by `request_id` — never here.
46	#[derive(Clone)]
47	pub(crate) struct PendingRequest {
48	    pub(crate) request_id: RequestId,
49	    pub(crate) lora_adapter: Option<String>,
50	    pub(crate) prompt_tokens: Vec<u32>,
51	    pub(crate) params: SamplingParams,
52	    pub(crate) stop_policy: StopPolicy,
53	    pub(crate) max_tokens: usize,
54	    pub(crate) logprobs: Option<usize>,
55	    pub(crate) prompt_logprobs: Option<usize>,
56	    /// Whether this request has already been offered to async KV prefetch.
57	    /// Offered at most once; a no-hit offer leaves the request in the normal
58	    /// admission flow with this set so it isn't re-probed every tick.
59	    pub(crate) prefetch_offered: bool,
60	    /// Prompt tokens whose KV is already computed (prefix-cache hits plus
61	    /// chunks applied in earlier steps). Updated from the executor's
62	    /// authoritative position after every chunk.
63	    pub(crate) prefill_pos: usize,
64	    /// Prompt tokens to forward in the upcoming step. Set by
65	    /// `take_prefill_chunks` when the request is packed into a step.
66	    pub(crate) step_chunk: usize,
67	}
68	
69	impl PendingRequest {
70	    pub(crate) fn from_request(request_id: RequestId, req: Request) -> Self {
71	        Self {
72	            request_id,
73	            lora_adapter: req.lora_adapter,
74	            prompt_tokens: req.prompt_tokens,
75	            params: req.params,
76	            stop_policy: req.stop_policy,
77	            max_tokens: req.max_tokens,
78	            logprobs: req.logprobs,
79	            prompt_logprobs: req.prompt_logprobs,
80	            prefetch_offered: false,
81	            prefill_pos: 0,
82	            step_chunk: 0,
83	        }
84	    }
85	
86	    fn remaining_prompt_tokens(&self) -> usize {
87	        self.prompt_tokens.len() - self.prefill_pos
88	    }
89	}
90	
91	/// Pull the next prefill step set off the front of `prefilling`, capping the
92	/// step's total forwarded tokens at `max_prefill_tokens`. Each taken request
93	/// gets its per-step chunk recorded in `step_chunk`. Prompt-logprob requests need
94	/// logits for every prompt position in one forward, so they only run when
95	/// their whole remainder fits the profiled prefill bound. Under request-local
96	/// chunking, a request takes `min(remaining, max_prefill_tokens)` whole or skips
97	/// the step, so its chunk boundaries depend only on its own length and are
98	/// batch-invariant.
99	pub(crate) fn take_prefill_chunks(
100	    prefilling: &mut Vec<PendingRequest>,
101	    max_prefill_tokens: usize,
102	    request_local: bool,
103	) -> Vec<PendingRequest> {
104	    let mut budget = max_prefill_tokens;
105	    let mut taken: Vec<PendingRequest> = Vec::new();
106	    let mut i = 0;
107	    while i < prefilling.len() && budget > 0 {
108	        let remaining = prefilling[i].remaining_prompt_tokens();
109	        let chunk = if prefilling[i].prompt_logprobs.is_some() {
110	            if remaining > budget {
111	                i += 1;
112	                continue;
113	            }
114	            remaining
115	        } else if request_local {
116	            let desired = remaining.min(max_prefill_tokens);
117	            if desired > budget {
118	                i += 1;
119	                continue;
120	            }
121	            desired
122	        } else {
123	            remaining.min(budget)
124	        };
125	        let mut req = prefilling.remove(i);
126	        req.step_chunk = chunk;
127	        budget = budget.saturating_sub(chunk);
128	        taken.push(req);
129	    }
130	    // Whole-or-skip may select later requests; sort to match request-id-ordered results.
131	    taken.sort_by_key(|req| req.request_id);
132	    taken
133	}
134	
135	pub(crate) fn servable_len(max_context: usize, max_blocks: usize, block_size: usize) -> u32 {
136	    max_context
137	        .min(max_blocks.saturating_mul(block_size))
138	        .try_into()
139	        .unwrap_or(u32::MAX)
140	}
141	
142	// ── KV-offload prefetch admission helpers ────────────────────────────────
143	
144	/// Move requests whose async CPU-tier prefetch just settled from `loading`
145	/// back to the front of `deferred` — their KV is hot, so admit them first.
146	pub(crate) fn reclaim_ready_prefetch<E: ModelExecutor>(
147	    executor: &mut E,
148	    deferred: &mut Vec<PendingRequest>,
149	    loading: &mut Vec<PendingRequest>,
150	    // Free blocks already promised to admitted requests; a remote fetch that
151	    // resolves during this sweep must not reserve into them.
152	    reserve_floor: usize,
153	) {
154	    promote_ready(
155	        executor.drain_ready_prefetch(reserve_floor),
156	        deferred,
157	        loading,
158	    );
159	}
160	
161	/// Offer each not-yet-offered `deferred` request to async CPU-tier prefetch,
162	/// moving the ones that start loading out of `deferred` into `loading`. A
163	/// request that doesn't start a load (pure GPU hit, miss, or block pressure)
164	/// stays in `deferred`, flagged so it isn't re-probed next tick.
165	///
166	/// Prompt-logprob requests are never offered: their prefill forwards the whole prompt to
167	/// recover prompt logprobs and so skips `match_and_add_prefix` (see
168	/// `execute_prefill`). Prefetched blocks would never be matched/reused — they
169	/// would only park restored KV that admission credits but prefill can't spend,
170	/// starving the request under tight budgets. Leaving `prefetch_offered` unset
171	/// for prompt-logprob requests is harmless: the `req.prompt_logprobs.is_none()` guard keeps them from being probed.
172	pub(crate) fn offer_prefetch<E: ModelExecutor>(
173	    executor: &mut E,
174	    deferred: &mut Vec<PendingRequest>,
175	    loading: &mut Vec<PendingRequest>,
176	    // Free blocks already promised to admitted requests; the prefetch must
177	    // leave them untouched (see `ModelExecutor::begin_kv_prefetch`).
178	    reserve_floor: usize,
179	) {
180	    let mut keep = Vec::with_capacity(deferred.len());
181	    for mut req in deferred.drain(..) {
182	        if !req.prefetch_offered && req.prompt_logprobs.is_none() {
183	            req.prefetch_offered = true;
184	            if executor.begin_kv_prefetch(
185	                req.request_id,
186	                &req.prompt_tokens,
187	                req.lora_adapter.as_deref(),
188	                reserve_floor,
189	            ) {
190	                loading.push(req);
191	                continue;
192	            }
193	        }
194	        keep.push(req);
195	    }
196	    *deferred = keep;
197	}
198	
199	/// Block until at least one in-flight prefetch settles, then promote the
200	/// settled requests to `deferred`. Called only when the scheduler is otherwise
201	/// idle, so blocking on the DMA costs nothing.
202	pub(crate) fn block_on_loading<E: ModelExecutor>(
203	    executor: &mut E,
204	    deferred: &mut Vec<PendingRequest>,
205	    loading: &mut Vec<PendingRequest>,
206	    reserve_floor: usize,
207	) {
208	    promote_ready(
209	        executor.wait_ready_prefetch(reserve_floor),
210	        deferred,
211	        loading,
212	    );
213	}
214	
215	fn promote_ready(
216	    ready: Vec<RequestId>,
217	    deferred: &mut Vec<PendingRequest>,
218	    loading: &mut Vec<PendingRequest>,
219	) {
220	    for id in ready {
221	        if let Some(pos) = loading.iter().position(|p| p.request_id == id) {
222	            deferred.insert(0, loading.remove(pos));
223	        }
224	    }
225	}
226	
227	/// Release any executor-side state a request accumulated before it was rejected
228	/// at admission. A rejected request never prefills, so the only state it can
229	/// hold is a settled KV prefetch — committed prefix blocks parked in the
230	/// executor while the request waited in `deferred`. Without this they would
231	/// leak (blocks pinned, map entry stranded) for the engine's lifetime. Idempotent
232	/// and harmless for requests that were never prefetched.
233	pub(crate) fn release_rejected<E: ModelExecutor>(
234	    executor: &mut E,
235	    tracker: &mut phase_trace::PhaseTracker,
236	    req: &PendingRequest,
237	) {
238	    // Close the request's queue span and drop its tracker entry; a rejected
239	    // request never reaches prefill/decode, so this is its only cleanup point.
240	    tracker.finish(req.request_id);
241	    if let Err(e) = executor.drop_request(req.request_id) {
242	        warn!(
243	            "failed to release state for rejected {:?}: {e}",
244	            req.request_id
245	        );
246	    }
247	}
248	
249	// ── Admission ───────────────────────────────────────────────────────────
250	
251	/// Why a request was rejected at admission, so the client gets an accurate error.
252	#[derive(Clone, Copy)]
253	pub(crate) enum RejectReason {
254	    /// Worst-case length exceeds the model's position-encoding window.
255	    ContextLength { limit: usize },
256	    /// Prompt scoring needs all-position logits in one forward, so it must fit the
257	    /// profiled prefill bound.
258	    EchoPrefillTokens { limit: usize },
259	    /// Worst-case length needs more KV blocks than this instance can ever provide.
260	    KvBudget,
261	}
262	
263	pub(crate) struct AdmissionOutcome {
264	    pub(crate) pending: Vec<PendingRequest>,
265	    pub(crate) deferred: Vec<PendingRequest>,
266	    pub(crate) rejected: Vec<(PendingRequest, RejectReason)>,
267	}
268	
269	pub(crate) struct LoraValidationOutcome {
270	    pub(crate) accepted: Vec<PendingRequest>,
271	    pub(crate) rejected: Vec<PendingRequest>,
272	}
273	
274	pub(crate) fn reject_unknown_lora_requests(
275	    deferred: Vec<PendingRequest>,
276	    executor: &impl ModelExecutor,
277	) -> LoraValidationOutcome {
278	    if !deferred.iter().any(|req| req.lora_adapter.is_some()) {
279	        return LoraValidationOutcome {
280	            accepted: deferred,
281	            rejected: Vec::new(),
282	        };
283	    }
284	
285	    let loaded_lora_adapters = executor.list_lora_adapters();
286	    let loaded_lora_adapters: HashSet<_> = loaded_lora_adapters.into_iter().collect();
287	    let mut accepted = Vec::new();
288	    let mut rejected = Vec::new();
289	
290	    for req in deferred {
291	        match req.lora_adapter.as_ref() {
292	            Some(adapter) if !loaded_lora_adapters.contains(adapter) => rejected.push(req),
293	            _ => accepted.push(req),
294	        }
295	    }
296	
297	    LoraValidationOutcome { accepted, rejected }
298	}
299	
300	fn blocks_needed(token_count: usize, block_size: usize) -> usize {
301	    token_count.div_ceil(block_size)
302	}
303	
304	// Prefill samples the first output token but does not write its KV. A generated
305	// token's KV is written only when it is fed as the next decode input. Therefore
306	// N returned completion tokens occupy at most N - 1 generated-token KV slots.
307	pub(crate) fn max_request_tokens(req: &PendingRequest) -> usize {
308	    req.prompt_tokens
309	        .len()
310	        .saturating_add(req.max_tokens.saturating_sub(1))
311	}
312	
313	#[cfg(test)]
314	fn max_active_tokens(req: &ActiveRequestState) -> usize {
315	    req.prompt_len
316	        .saturating_add(req.max_tokens.saturating_sub(1))
317	}
318	
319	fn current_active_tokens(req: &ActiveRequestState) -> usize {
320	    req.prompt_len
321	        .saturating_add(req.generated_count.saturating_sub(1))
322	}
323	
324	// Pool blocks a request can draw over its lifetime. One-token completions
325	// finish after prefill, so schedule_decode never provisions a dangling block.
326	// Multi-token requests can draw that final dangling decode block, so admission
327	// reserves prompt + max_tokens for them.
328	fn request_lifetime_blocks(prompt_len: usize, max_tokens: usize, block_size: usize) -> usize {
329	    let lifetime_tokens = if max_tokens <= 1 {
330	        prompt_len
331	    } else {
332	        prompt_len.saturating_add(max_tokens)
333	    };
334	    lifetime_tokens.div_ceil(block_size).max(1)
335	}
336	
337	fn pending_lifetime_blocks(req: &PendingRequest, block_size: usize) -> usize {
338	    request_lifetime_blocks(req.prompt_tokens.len(), req.max_tokens, block_size)
339	}
340	
341	fn active_lifetime_blocks(req: &ActiveRequestState, block_size: usize) -> usize {
342	    request_lifetime_blocks(req.prompt_len, req.max_tokens, block_size)
343	}
344	
345	fn active_future_blocks(active: &[ActiveRequestState], block_size: usize) -> usize {
346	    active
347	        .iter()
348	        .map(|req| {
349	            active_lifetime_blocks(req, block_size)
350	                .saturating_sub(blocks_needed(current_active_tokens(req), block_size))
351	        })
352	        .sum()
353	}
354	
355	fn prompt_logprobs_exceeds_prefill_bound(req: &PendingRequest, max_prefill_tokens: usize) -> bool {
356	    req.prompt_logprobs.is_some() && req.prompt_tokens.len() > max_prefill_tokens
357	}
358	
359	/// Free blocks already promised to admitted requests (active decode growth +
360	/// remaining prefill chunks). A KV prefetch reservation must stay out of this
361	/// floor or a later chunk/decode fails allocation and kills the whole step.
362	pub(crate) fn admitted_future_blocks<E: ModelExecutor>(
363	    executor: &E,
364	    active: &[ActiveRequestState],
365	    prefilling: &[PendingRequest],
366	    inflight: &[PendingRequest],
367	) -> usize {
368	    let block_size = executor.block_size();
369	    active_future_blocks(active, block_size)
370	        + prefilling_future_blocks(prefilling, inflight, block_size, |id| {
371	            executor.prefetched_blocks(id)
372	        })
373	}
374	
375	/// An in-flight prefill already holds its launched chunk, so its debt starts at
376	/// `prefill_pos + step_chunk`; a queued one starts at `prefill_pos`.
377	fn prefilling_future_blocks(
378	    prefilling: &[PendingRequest],
379	    inflight: &[PendingRequest],
380	    block_size: usize,
381	    // Blocks a request already holds via a settled prefetch (zero once its
382	    // first chunk absorbs them). They are out of the free pool, so counting
383	    // them as future need would double-charge the budget.
384	    prefetch_credit: impl Fn(RequestId) -> usize,
385	) -> usize {
386	    let owed = |req: &PendingRequest, allocated_tokens: usize| {
387	        pending_lifetime_blocks(req, block_size)
388	            .saturating_sub(blocks_needed(allocated_tokens, block_size))
389	            .saturating_sub(prefetch_credit(req.request_id))
390	    };
391	    let queued: usize = prefilling
392	        .iter()
393	        .map(|req| owed(req, req.prefill_pos))
394	        .sum();
395	    let launched: usize = inflight
396	        .iter()
397	        .map(|req| owed(req, req.prefill_pos + req.step_chunk))
398	        .sum();
399	    queued + launched
400	}
401	
402	/// Default for `max_prefill_tokens`: prompt tokens forwarded in a single step
403	/// (chunked prefill). Prefill activation scratch scales with the step's total
404	/// prompt tokens (~22 KB/token measured on Qwen3-4B), so an unbounded prefill
405	/// batch can eat the post-KV-pool VRAM headroom and OOM mid-serving under a
406	/// request burst. Prompts longer than the budget are split across steps, so
407	/// long prompts can't monopolize a step and starve running decodes.
408	/// Prompt-logprob requests need all-position logits in one forward and are rejected when
409	/// their prompt exceeds this bound.
410	///
411	/// A unified step's duration scales with its prefill tokens, and every decode
412	/// request in the batch stalls for the whole step — the budget bounds that
413	/// stall. 1024 halves ITL p99 vs 2048 at mid-load with the same mean TPOT;
414	/// 512 chunks no longer amortize the per-step fixed cost, so prefill falls
415	/// behind arrivals and TTFT queues up.
416	pub const DEFAULT_MAX_PREFILL_TOKENS: usize = 1024;
417	
418	#[allow(clippy::too_many_arguments)]
419	pub(crate) fn admit_deferred_requests(
420	    deferred: Vec<PendingRequest>,
421	    active: &[ActiveRequestState],
422	    // Admitted requests still mid-prefill: they hold KV for their applied
423	    // chunks and will take a decode slot when they promote, so admission
424	    // must reserve both or completing chunks can overshoot capacity.
425	    prefilling: &[PendingRequest],
426	    // Decode-overlap prefills still running on the GPU: out of `prefilling`
427	    // until their result is applied, but owed the same KV tail and slot.
428	    inflight: &[PendingRequest],
429	    block_size: usize,
430	    available_blocks: usize,
431	    max_request_blocks: usize,
432	    max_context_tokens: usize,
433	    max_decode_batch_size: usize,
434	    max_prefill_tokens: usize,
435	    // Blocks a request already holds from a settled prefetch. These are already
436	    // out of `available_blocks`, so they must be credited against the request's
437	    // need or admission double-counts them and can wedge a near-budget CPU-hit
438	    // request forever (never admitted, prefetch never released).
439	    prefetch_credit: impl Fn(RequestId) -> usize,
440	) -> AdmissionOutcome {
441	    let mut budget = available_blocks
442	        .saturating_sub(active_future_blocks(active, block_size))
443	        .saturating_sub(prefilling_future_blocks(
444	            prefilling,
445	            inflight,
446	            block_size,
447	            &prefetch_credit,
448	        ));
449	    let mut decode_slots = max_decode_batch_size
450	        .saturating_sub(active.len())
451	        .saturating_sub(prefilling.len())
452	        .saturating_sub(inflight.len());
453	    let mut pending = Vec::new();
454	    let mut still_deferred = Vec::new();
455	    let mut rejected = Vec::new();
456	
457	    for req in deferred {
458	        // Reject if the full sequence overflows the position-encoding window
459	        if req.prompt_tokens.len().saturating_add(req.max_tokens) > max_context_tokens {
460	            rejected.push((
461	                req,
462	                RejectReason::ContextLength {
463	                    limit: max_context_tokens,
464	                },
465	            ));
466	            continue;
467	        }
468	
469	        if prompt_logprobs_exceeds_prefill_bound(&req, max_prefill_tokens) {
470	            rejected.push((
471	                req,
472	                RejectReason::EchoPrefillTokens {
473	                    limit: max_prefill_tokens,
474	                },
475	            ));
476	            continue;
477	        }
478	
479	        // Full physical footprint gates the per-request cap (a request occupies
480	        // all of it, prefetched or not)…
481	        let footprint = pending_lifetime_blocks(&req, block_size);
482	        if footprint > max_request_blocks {
483	            rejected.push((req, RejectReason::KvBudget));
484	            continue;
485	        }
486	
487	        // …but only the blocks not already held by this request's prefetch must
488	        // come from the free-pool budget.
489	        let fresh_needed = footprint.saturating_sub(prefetch_credit(req.request_id));
490	        if fresh_needed <= budget && decode_slots > 0 {
491	            budget -= fresh_needed;
492	            decode_slots -= 1;
493	            debug!(
494	                "request admitted: request_id={:?} prompt_len={} max_tokens={}",
495	                req.request_id,
496	                req.prompt_tokens.len(),
497	                req.max_tokens
498	            );
499	            pending.push(req);
500	        } else {
501	            still_deferred.push(req);
502	        }
503	    }
504	
505	    AdmissionOutcome {
506	        pending,
507	        deferred: still_deferred,
508	        rejected,
509	    }
510	}
511	
512	/// Choose the step plan, preferring a speculative-decode step when the whole
513	/// active batch is draft-ready. Prefill of new arrivals still takes priority —
514	/// a speculative step only runs when there is nothing to prefill, so the two
515	/// never mix in one step.
516	pub(crate) fn runtime_plan(
517	    executor: &impl ModelExecutor,
518	    active: &[ActiveRequestState],
519	    pending: Vec<PendingRequest>,
520	) -> Option<plan::ExecutionPlan> {
521	    runtime_plan_at(executor, active, pending, plan::spec_max_batch())
522	}
523	
524	/// [`runtime_plan`] with the load gate's threshold passed in, so the gate is
525	/// testable without mutating process-wide env state.
526	fn runtime_plan_at(
527	    executor: &impl ModelExecutor,
528	    active: &[ActiveRequestState],
529	    pending: Vec<PendingRequest>,
530	    max_batch: usize,
531	) -> Option<plan::ExecutionPlan> {
532	    use plan::SpeculationDecision;
533	    match plan::speculation_decision_at(executor, active, max_batch) {
534	        SpeculationDecision::Speculate => {
535	            if pending.is_empty() {
536	                Some(plan::ExecutionPlan::SpeculativeDecode)
537	            } else {
538	                Some(plan::ExecutionPlan::Prefill { pending })
539	            }
540	        }
541	        SpeculationDecision::Gated => {
542	            if pending.is_empty() {
543	                Some(plan::ExecutionPlan::GatedSpeculativeDecode)
544	            } else {
545	                Some(plan::ExecutionPlan::Prefill { pending })
546	            }
547	        }
548	        SpeculationDecision::NotReady => {
549	            plan::build_next_plan(!active.is_empty(), pending, executor.speculative_enabled())
550	        }
551	    }
552	}
553	
554	/// The requests a plan's execution failure kills: the batch it was about to
555	/// touch. Computed before execution so the ids survive the error path.
556	pub(crate) fn failure_target_ids(
557	    active: &[ActiveRequestState],
558	    plan: &plan::ExecutionPlan,
559	) -> Vec<RequestId> {
560	    let mut targets = Vec::new();
561	    match plan {
562	        plan::ExecutionPlan::Prefill { pending } => {
563	            targets.extend(pending.iter().map(|req| req.request_id));
564	        }
565	        plan::ExecutionPlan::Decode
566	        | plan::ExecutionPlan::SpeculativeDecode
567	        | plan::ExecutionPlan::GatedSpeculativeDecode => {
568	            targets.extend(active.iter().map(|req| req.request_id));
569	        }
570	        plan::ExecutionPlan::Unified { pending } => {
571	            targets.extend(active.iter().map(|req| req.request_id));
572	            targets.extend(pending.iter().map(|req| req.request_id));
573	        }
574	    }
575	    targets
576	}
577	
